class Animal {
    protected String name;

    public Animal(String name) {
        this.name = name;
    }

    public String makeSound() {
        return name + " makes a generic sound";
    }
}

class Dog extends Animal {
    public Dog(String name) {
        super(name); // gọi constructor của Animal
    }

    @Override
    public String makeSound() {
        return name + " barks"; // truy cập field kế thừa từ Animal
    }
}

class Base {
    protected int level = 1;
}

class Advanced extends Base {
    protected int level = 2; // che field 'level' của Base

    public void printLevels() {
        System.out.println("this.level = " + this.level);   // 2
        System.out.println("super.level = " + super.level); // 1
    }
}

class Shape {
    public double area() {
        return 0;
    }

    // method overloading: cung ten describe, khac danh sach tham so
    public String describe() {
        return "Shape with area " + area();
    }

    public String describe(String prefix) {
        return prefix + ": " + describe();
    }
}

class Circle extends Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override // method overriding: cùng chữ ký với Shape.area()
    public double area() {
        return Math.PI * radius * radius;
    }
}

class PolymorphismDemo {
    public static void main(String[] args) {
        Shape shape = new Circle(2.0); // bien khai bao kieu Shape
        System.out.println(shape.describe()); // goi Circle.area() luc runtime
    }
}

class Shape {
    public double area() {
        return 0;
    }
}

class Circle extends Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
}

class DowncastDemo {
    public static void main(String[] args) {
        Shape shape = new Circle(1.5);

        if (shape instanceof Circle circle) { // downcast an toan
            System.out.println("radius-based area: " + circle.area());
        } else {
            System.out.println("Khong phai Circle, bo qua downcast");
        }
    }
}

abstract class Vehicle {
    protected final String plateNumber;

    protected Vehicle(String plateNumber) {
        this.plateNumber = plateNumber;
    }

    public abstract double calculateTollFee(); // bat buoc lop con cai dat

    public String getPlateNumber() { // code dùng chung, không cần override
        return plateNumber;
    }
}

class Motorbike extends Vehicle {
    public Motorbike(String plateNumber) {
        super(plateNumber);
    }

    @Override
    public double calculateTollFee() {
        return 5000.0;
    }
}

